import{_ as r,o as e,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-06-22","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-06-22","date":"2021-06-22T00:00:00.000Z","updated":"2021-06-24T00:00:00.000Z","tags":["Ceph","Orchestrator","Kubernetes","Rook","SSH"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-06-22.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-06-22.md","lastUpdated":1780460162000}'),i={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-06-22.md"};function l(n,a,s,h,c,d){return e(),t("div",null,[...a[0]||(a[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-orchestrator-周例会" tabindex="-1">会议主题：Orchestrator 周例会 <a class="header-anchor" href="#会议主题-orchestrator-周例会" aria-label="Permalink to &quot;会议主题：Orchestrator 周例会&quot;">​</a></h4><h4 id="会议时间-2021年6月22日" tabindex="-1">会议时间：2021年6月22日 <a class="header-anchor" href="#会议时间-2021年6月22日" aria-label="Permalink to &quot;会议时间：2021年6月22日&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议议程" tabindex="-1">会议议程： <a class="header-anchor" href="#会议议程" aria-label="Permalink to &quot;会议议程：&quot;">​</a></h4><ol><li><strong>KCLI 项目进展</strong></li><li><strong>Paramecio 适用性问题</strong></li></ol><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><h5 id="_1-kcli-项目进展" tabindex="-1">1. KCLI 项目进展 <a class="header-anchor" href="#_1-kcli-项目进展" aria-label="Permalink to &quot;1. KCLI 项目进展&quot;">​</a></h5><ul><li><strong>项目介绍</strong>：介绍了使用 KCLI 项目通过 Rook 操作符在 Kubernetes 集群中设置和启动 Ceph 集群的新计划。</li><li><strong>技术细节</strong>：讨论了进行测试所需的资源，如内存和硬盘空间，并探讨如何简化开发和集成测试过程。</li><li><strong>工具对比</strong>：比较了 KCLI 和 Vagrant，讨论了各自的优缺点，以及是否需要安装额外的工具。</li><li><strong>团队反馈</strong>：欢迎团队成员提出意见和建议。</li></ul><h5 id="_2-paramecio-适用性问题" tabindex="-1">2. Paramecio 适用性问题 <a class="header-anchor" href="#_2-paramecio-适用性问题" aria-label="Permalink to &quot;2. Paramecio 适用性问题&quot;">​</a></h5><ul><li><strong>问题描述</strong>：讨论了 Paramecio 作为 SSH 封装层存在功能限制和错误信息隐藏的问题。</li><li><strong>替代方案</strong>：探讨了使用 ZincSSH 或其他库的可能性，并考虑是否需要一个同步库。</li><li><strong>技术挑战</strong>：讨论了如何处理远程主机上的多命令执行问题，包括使用持久性 SSH 连接或远程 Python 解释器。</li><li><strong>团队决策</strong>：初步决定尝试使用 AsyncSSH，并考虑移除对 Remoto 的依赖。</li></ul><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li><strong>KCLI 项目</strong>：继续推进 KCLI 项目，收集团队反馈以优化工具选择和使用。</li><li><strong>Paramecio 问题</strong>：尝试使用 AsyncSSH 作为替代方案，评估其适用性和性能。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li><strong>KCLI 项目</strong>：团队成员需提供关于 KCLI 和 Vagrant 的使用反馈，以便进一步优化开发环境。</li><li><strong>Paramecio 问题</strong>：进行 AsyncSSH 的实验性测试，评估其是否能满足项目需求，并解决多命令执行的问题。</li></ul><h4 id="其他事项" tabindex="-1">其他事项： <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项：&quot;">​</a></h4><ul><li><strong>RGW 集成测试</strong>：确认 RGW 集成测试的进展，计划进行测试套件的转换工作。</li><li><strong>NFS 和 Dashboard 工作</strong>：继续推进 NFS 相关工作和 Dashboard 模块的改进。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><p>会议于[具体时间]结束，下次会议定于下周进行。</p>',19)])])}const _=r(i,[["render",l]]);export{u as __pageData,_ as default};
